SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;
-- ge_admins DDL
CREATE TABLE `sys_admins` (`uid` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
`username` VARCHAR(16) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`password` VARCHAR(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`salt` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`email` VARCHAR(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`role` SMALLINT(5) UNSIGNED NULL,
`status` TINYINT(3) UNSIGNED NULL DEFAULT 1 Comment "1=正常，2=冻结",
INDEX `group`(`role` ASC) USING BTREE,
UNIQUE INDEX `username`(`username` ASC) USING BTREE,
PRIMARY KEY (`uid`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 4 ROW_FORMAT = Dynamic;
-- ge_backend_settings DDL
CREATE TABLE `sys_backend_settings` (`backend_theme` VARCHAR(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`backend_lang` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`backend_root_access` TINYINT(3) UNSIGNED NULL DEFAULT 1,
`backend_access_point` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'admin',
`backend_title` VARCHAR(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'DiliCMS后台管理',
`backend_logo` VARCHAR(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'images/logo.gif',
`plugin_dev_mode` TINYINT(3) UNSIGNED NOT NULL DEFAULT 0,
`backend_http_auth_on` TINYINT(3) NULL DEFAULT 0,
`backend_http_auth_user` VARCHAR(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`backend_http_auth_password` VARCHAR(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 2 ROW_FORMAT = Dynamic;
-- ge_fieldtypes DDL
CREATE TABLE `sys_fieldtypes` (`k` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`v` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 13 ROW_FORMAT = Dynamic;
-- ge_group DDL
CREATE TABLE `sys_group` (`id` MEDIUMINT(7) NOT NULL AUTO_INCREMENT,
`name` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`description` VARCHAR(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`level` INT(10) NULL,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 31 ROW_FORMAT = Dynamic;
-- ge_model_fields DDL
CREATE TABLE `sys_model_fields` (`id` MEDIUMINT(7) UNSIGNED NOT NULL AUTO_INCREMENT,
`name` VARCHAR(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`description` VARCHAR(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`model` SMALLINT(5) UNSIGNED NOT NULL DEFAULT 0,
`type` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`length` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`values` TEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`width` SMALLINT(5) UNSIGNED NOT NULL,
`height` SMALLINT(5) UNSIGNED NOT NULL,
`rules` TINYTEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`ruledescription` TINYTEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`searchable` TINYINT(3) UNSIGNED NOT NULL,
`listable` TINYINT(3) UNSIGNED NOT NULL,
`order` INT(10) UNSIGNED NULL,
`editable` TINYINT(3) UNSIGNED NULL DEFAULT 1,
INDEX `model`(`model` ASC) USING BTREE,
UNIQUE INDEX `name`(`name` ASC,`model` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 1140 ROW_FORMAT = Dynamic;
-- ge_models DDL
CREATE TABLE `sys_models` (`id` SMALLINT(5) UNSIGNED NOT NULL AUTO_INCREMENT,
`name` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`description` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`perpage` VARCHAR(2) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '10',
`hasattach` TINYINT(3) UNSIGNED NOT NULL DEFAULT 0,
`built_in` TINYINT(3) UNSIGNED NOT NULL DEFAULT 0,
`thumb_preferences` TEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`belong_group` SMALLINT(5) NOT NULL,
`model_sort` INT(10) NOT NULL DEFAULT 0,
UNIQUE INDEX `name`(`name` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 195 ROW_FORMAT = Dynamic;
-- ge_roles DDL
CREATE TABLE `sys_roles` (`id` INT(10) NOT NULL AUTO_INCREMENT,
`name` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`rights` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`models` VARCHAR(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`category_models` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`plugins` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
UNIQUE INDEX `name`(`name` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 6 ROW_FORMAT = Dynamic;
-- ge_sessions DDL
CREATE TABLE `sys_sessions` (`session_id` VARCHAR(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
`ip_address` VARCHAR(16) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
`user_agent` VARCHAR(120) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`last_activity` INT(10) UNSIGNED NOT NULL DEFAULT 0,
`user_data` TEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
INDEX `last_activity_idx`(`last_activity` ASC) USING BTREE,
PRIMARY KEY (`session_id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;
-- ge_site_settings DDL
CREATE TABLE `sys_site_settings` (`site_name` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_domain` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_logo` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_icp` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_terms` TEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_stats` VARCHAR(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_footer` VARCHAR(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_status` TINYINT(3) NULL DEFAULT 1,
`site_close_reason` VARCHAR(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_keyword` VARCHAR(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_description` VARCHAR(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`site_theme` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`attachment_url` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`attachment_dir` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`attachment_type` VARCHAR(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`attachment_maxupload` VARCHAR(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`thumbs_preferences` VARCHAR(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '[]') ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 2 ROW_FORMAT = Dynamic;
-- ge_throttles DDL
CREATE TABLE `sys_throttles` (`id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
`user_id` INT(10) NULL,
`type` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
`ip` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 8 ROW_FORMAT = Dynamic;
